 id: 'vzduch', title: 'Vzduch', aka: ['Zloženie vzduchu', 'Kyslík a dusík', 'Ovzdušie', 'Znečistenie ovzdušia'], subject: 'Chémia', grade: 7, kind: 'pojmy', rec: 'mind',
