  plan: [['5 min', 'Glóbus: koľko je na Zemi vody a koľko pevniny?'], ['15 min', 'Myšlienková mapa svetadielov a oceánov.'], ['15 min', 'Puzzle: žiaci priraďujú vystrihnuté svetadiely na slepú mapu.'], ['10 min', 'Hra „Kde som?“ a kvíz.']],
