{
 id: 'fazy-mesiaca', title: 'Mesiac a jeho fázy', aka: ['Fázy Mesiaca', 'Mesiac', 'Spln a nov', 'Mesačné fázy'], subject: 'Človek a príroda', grade: 4, kind: 'proces', rec: 'cycle',
 why: 'Fázy Mesiaca sa pravidelne opakujú. Cyklus ukáže nov, štvrte a spln ako kolobeh, ktorý trvá približne mesiac.',
 alts: [['scene', 'Keď chcete ukázať, ako Slnko osvetľuje Mesiac obiehajúci okolo Zeme.'], ['cards', 'Na opakovanie názvov fáz.'], ['quiz', 'Na rýchle overenie.']],
 std: ['S209', 'S210', 'S4793'],
 method: { goals: ['Žiak vysvetlí, že Mesiac nesvieti sám, ale odráža svetlo Slnka.', 'Žiak pomenuje fázy Mesiaca v správnom poradí.', 'Žiak uvedie, že Mesiac obehne Zem približne za 27 dní a fázy sa opakujú približne po 29 a pol dni.'],
  plan: [['5 min', 'Otázka: prečo Mesiac na oblohe mení tvar?'], ['10 min', 'Cyklus fáz Mesiaca.'], ['20 min', 'Model: lampa ako Slnko, loptička na paličke ako Mesiac, hlava žiaka ako Zem.'], ['10 min', 'Pozorovací kalendár na mesiac a kvíz.']],
  ask: ['Svieti Mesiac sám?', 'Prečo vidíme stále tú istú stranu Mesiaca?'] },
 guide: { primer: 'Mesiac je prirodzená družica Zeme. Obehne ju približne za 27 dní. Mesiac sám nesvieti, odráža svetlo zo Slnka. Slnko osvetľuje vždy polovicu Mesiaca, my však podľa jeho polohy vidíme z osvetlenej časti rôzne veľa. Preto pozorujeme fázy: nov, keď Mesiac voľným okom spravidla nevidíme, prvú štvrť, spln, keď vidíme celý kotúč, a poslednú štvrť. Rovnaké fázy sa opakujú približne po 29 a pol dni. Je to o niečo dlhšie ako obeh, lebo Zem sa medzitým posunie na svojej ceste okolo Slnka. Mesiac sa k Zemi otáča stále tou istou stranou.',
  steps: [
   { time: '5 min', do: 'Ukážte fotografie Mesiaca v rôznych fázach.', say: 'Mení Mesiac naozaj tvar?', check: 'Žiaci vyslovia domnienky, ktoré neskôr overíme.' },
   { time: '10 min', do: 'Prejdite cyklus fáz.', say: 'Kedy je Mesiac medzi Zemou a Slnkom?', check: 'Žiaci spoja nov s polohou medzi Zemou a Slnkom.' },
   { time: '20 min', do: 'Zatemnite triedu. Žiak drží loptičku pred sebou a pomaly sa otáča okolo seba pri rozsvietenej lampe. Ostatní hovoria, akú fázu vidí.', check: 'Žiaci vidia všetky fázy a vedia, kde bola loptička pri splne.' },
   { time: '10 min', do: 'Rozdajte pozorovací kalendár na mesiac. Kvíz.', check: 'Žiaci vedia, kedy a kam sa majú pozerať.' }],
  traps: [['Mesiac svieti ako Slnko.', 'Mesiac iba odráža svetlo Slnka.'], ['Fázy spôsobuje tieň Zeme.', 'Tieň Zeme spôsobuje iba zatmenie Mesiaca. Fázy vznikajú tým, že vidíme rôznu časť osvetlenej polovice.'], ['Mesiac je vidieť iba v noci.', 'Mesiac často vidíme aj cez deň.']],
  qa: [['Ako spoznám, či Mesiac dorastá?', 'U nás platí: keď je osvetlená pravá strana a Mesiac pripomína písmeno D, dorastá. Keď pripomína C, ubúda.'], ['Prečo máme na Mesiaci škvrny?', 'Sú to tmavšie roviny, ktoré vznikli zo stuhnutej lávy. Volajú sa moria, hoci v nich nie je voda.']] },
 forms: {
  cycle: { hub: 'Fázy Mesiaca', steps: [
   { t: 'Nov', d: 'Mesiac je medzi Zemou a Slnkom. Osvetlená strana je odvrátená, voľným okom ho spravidla nevidíme.', e: 'Mesiac spravidla nevidíme.', ic: 'cloud' },
   { t: 'Prvá štvrť', d: 'Vidíme osvetlenú pravú polovicu kotúča. Mesiac dorastá.', e: 'Vidíme pravú polovicu Mesiaca.', ic: 'star' },
   { t: 'Spln', d: 'Zem je medzi Slnkom a Mesiacom. Vidíme celý osvetlený kotúč.', e: 'Vidíme celý Mesiac.', ic: 'sun' },
   { t: 'Posledná štvrť', d: 'Vidíme osvetlenú ľavú polovicu kotúča. Mesiac ubúda až do novu.', e: 'Vidíme ľavú polovicu Mesiaca.', ic: 'star' }] },
  scene: { svg: `<svg viewBox="0 0 1200 640" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="640" fill="#0d1b2a"/><g fill="#ffffff" opacity="0.7"><circle cx="1100" cy="60" r="2"/><circle cx="1000" cy="580" r="2"/><circle cx="700" cy="40" r="2"/><circle cx="420" cy="600" r="2"/><circle cx="850" cy="300" r="2"/></g><circle cx="80" cy="320" r="120" fill="#ffd54f"><animate attributeName="r" values="116;124;116" dur="4s" repeatCount="indefinite"/></circle><g stroke="#ffe082" stroke-width="2" opacity="0.4"><path d="M200 220H1200M200 320H1200M200 420H1200"/></g><circle cx="640" cy="320" r="190" fill="none" stroke="#546e7a" stroke-width="2" stroke-dasharray="8 10"/><circle cx="640" cy="320" r="60" fill="#1e88e5"/><path d="M640 260a60 60 0 0 1 0 120z" fill="#0d47a1"/><path d="M610 300q20-20 40 0t30 20" stroke="#43a047" stroke-width="12" fill="none"/><g><animateTransform attributeName="transform" type="rotate" values="0 640 320;-360 640 320" dur="16s" repeatCount="indefinite"/><g transform="translate(830 320)"><circle r="34" fill="#424242"/><path d="M0 -34a34 34 0 0 0 0 68z" fill="#eeeeee"><animateTransform attributeName="transform" type="rotate" values="0;360" dur="16s" repeatCount="indefinite"/></path></g></g></svg>`,
   points: [{ t: 'Slnko', d: 'Slnko osvetľuje vždy polovicu Mesiaca, tú, ktorá je k nemu otočená.', e: 'Slnko svieti na Mesiac.', ic: 'sun', x: 7, y: 50 }, { t: 'Zem', d: 'Zo Zeme vidíme rôzne veľkú časť osvetlenej polovice Mesiaca.', e: 'Zo Zeme sa pozeráme na Mesiac.', ic: 'map', x: 53, y: 50 }, { t: 'Mesiac', d: 'Mesiac obehne Zem približne za 27 dní. Sám nesvieti.', e: 'Mesiac obieha okolo Zeme.', ic: 'star', x: 69, y: 50 }, { t: 'Dráha Mesiaca', d: 'Počas jedného obehu vidíme nov, prvú štvrť, spln a poslednú štvrť.', e: 'Pri obehu sa mení tvar Mesiaca.', ic: 'cross', x: 53, y: 18 }, { t: 'Odvrátená strana', d: 'Mesiac sa k Zemi otáča stále tou istou stranou, druhú zo Zeme nevidíme.', e: 'Jednu stranu Mesiaca nevidíme nikdy.', ic: 'cloud', x: 75, y: 76, l: 2 }] },
  cards: [{ q: 'Svieti Mesiac sám?', a: 'Nie, odráža svetlo Slnka.' }, { q: 'Ako sa volá fáza, keď Mesiac nevidíme?', a: 'Nov.' }, { q: 'Ako sa volá fáza, keď vidíme celý kotúč?', a: 'Spln.' }, { q: 'Za aký čas obehne Mesiac Zem?', a: 'Približne za 27 dní.' }, { q: 'Po koľkých dňoch sa opakuje spln?', a: 'Približne po 29 a pol dni.', l: 2 }, { q: 'Ako spoznáš dorastajúci Mesiac?', a: 'Je osvetlený sprava a pripomína písmeno D.', l: 2 }, { q: 'Prečo vidíme stále tú istú stranu Mesiaca?', a: 'Mesiac sa otočí okolo seba za rovnaký čas, ako obehne Zem.', l: 3 }],
  quiz: [{ q: 'Čo je Mesiac?', o: ['Prirodzená družica Zeme', 'Hviezda', 'Planéta'], k: 0, w: 'Mesiac obieha okolo Zeme.' }, { q: 'Ktorá fáza nasleduje po prvej štvrti?', o: ['Spln', 'Nov', 'Posledná štvrť'], k: 0, w: 'Mesiac dorastá od novu cez prvú štvrť až do splnu.' }, { q: 'Prečo sa mení tvar Mesiaca?', o: ['Vidíme rôznu časť jeho osvetlenej polovice', 'Mesiac sa zmenšuje', 'Zakrývajú ho mraky'], k: 0, w: 'Slnko osvetľuje vždy polovicu, my ju vidíme z rôznych strán.' }, { q: 'Kde je Mesiac počas novu?', o: ['Medzi Zemou a Slnkom', 'Za Zemou', 'Pri Marse'], k: 0, w: 'Osvetlená strana je vtedy odvrátená od nás.', l: 2 }],
  vvn: { know: ['Aký tvar mal Mesiac, keď si ho videl naposledy?', 'Vieš, kedy je spln?'], want: ['Prečo Mesiac mení tvar?', 'Prečo ho vidíme aj cez deň?'], learned: ['Nakresli fázy Mesiaca v poradí.', 'Mesiac každý večer pozoruj a zakresli ho.'] } } }
